import { policyEffectMarkup } from './effect-ui.js';
import { LAWS, DECISIONS, PROFILES, policyEffects, PROFILE_REASONS, lawChangeCost, lawBlock } from './governance.js';
export const profileMarkup = id => `<p class="note">${policyEffectMarkup(PROFILES[id])}</p><p class="note">${PROFILE_REASONS[id]}</p>`;
export function governancePanel(state, mode) {
  const g = state.governance, lawCost = lawChangeCost(state);
  const overview = `<div class="detail-card"><strong>Aktuelle Gesamtwirkung</strong><p>${policyEffectMarkup(Object.fromEntries(Object.entries(policyEffects(state)).filter(([k, v]) => v !== (k === 'happiness' ? 0 : 1))))}</p></div>`;
  if (mode === 'laws') return `<p class="lede">Grundgesetze stehen allen Regierungen offen. Weitergehende Gesetze passen zur Staatsform und benötigen teilweise Forschung. Änderungen kosten ${lawCost} ¢ und ${(3 * policyEffects(state).reformStability).toFixed(1).replace('.', ',')} Stabilität. Zwischen Änderungen liegen fünf Tage.</p>${g.lawReady > state.day ? `<div class="alert">Verwaltung beschäftigt: noch ${g.lawReady - state.day} Tage.</div>` : ''}${overview}${Object.entries(LAWS).map(([id, law]) => `<div class="section-title">${law.name}</div>${Object.entries(law.options).filter(([,o])=>!o.ideologies||o.ideologies.includes(state.player.ideology)).map(([choice, option]) => `<div class="detail-card"><div class="card-heading"><strong>${option.name}</strong>${g.laws[id] === choice ? '<span class="status-badge">Gilt</span>' : ''}</div><p>${policyEffectMarkup(option.effects)}</p>${lawBlock(state,id,choice)?`<p class="note">${lawBlock(state,id,choice)}</p>`:""}<button class="button secondary" data-action="law-enact" data-category="${id}" data-choice="${choice}" ${lawBlock(state,id,choice) || g.laws[id] === choice || g.lawReady > state.day || state.credits < lawCost ? 'disabled' : ''}>Gesetz erlassen · ${lawCost} ¢</button></div>`).join('')}`).join('')}`;
  return `<p class="lede">Zeitlich begrenzte Programme wirken auf alle eigenen Planeten. Unterschiedliche Programme lassen sich kombinieren; derselbe Beschluss hat eine Sperrfrist.</p>${overview}${Object.entries(DECISIONS).filter(([,d])=>!d.ideologies||d.ideologies.includes(state.player.ideology)).map(([id, d]) => {
    const active = g.decisions.find(a => a.id === id), wait = Math.max(0, (g.cooldowns[id] ?? 0) - state.day);
    return `<div class="detail-card"><div class="card-heading"><strong>${d.name}</strong>${active ? `<span class="status-badge">${active.until - state.day} Tage</span>` : ''}</div><p>${d.description}</p>${d.requiredTech&&!state.tech.includes(d.requiredTech)?'<p class="note">Benötigt: Institutionelle Reformverfahren</p>':''}<p class="note">${policyEffectMarkup(d.effects)}<br>${d.duration} Tage Laufzeit · ${d.cooldown} Tage bis erneut verfügbar</p><button class="button secondary" data-action="government-decision" data-id="${id}" ${wait || d.requiredTech&&!state.tech.includes(d.requiredTech) || state.credits < d.cost ? 'disabled' : ''}>${wait ? `Erneut in ${wait} Tagen` : `Beschließen · ${d.cost} ¢`}</button></div>`;
  }).join('')}`;
}
